### Test Suite

```javascript
// ─── Valid Input Tests ────────────────────────────────────────────────────────

const validTests = [
  // Edge cases at boundaries
  { input: 0,    expected: "child"  },
  { input: 12,   expected: "child"  },
  { input: 12.9, expected: "child"  },
  { input: 13,   expected: "teen"   },
  { input: 19,   expected: "teen"   },
  { input: 19.9, expected: "teen"   },
  { input: 20,   expected: "adult"  },
  { input: 40,   expected: "adult"  },
  { input: 64,   expected: "adult"  },
  { input: 64.9, expected: "adult"  },
  { input: 65,   expected: "senior" },
  { input: 100,  expected: "senior" },
];

console.log("=== Valid Input Tests ===");
validTests.forEach(({ input, expected }) => {
  const result = classifyAge(input);
  const status = result === expected ? "✅ PASS" : "❌ FAIL";
  console.log(`${status} | classifyAge(${input}) → "${result}" (expected: "${expected}")`);
});

// ─── Invalid Input Tests ──────────────────────────────────────────────────────

const invalidTests = [
  { input: -1,         errorType: RangeError,  label: "negative number"   },
  { input: -0.1,       errorType: RangeError,  label: "negative decimal"  },
  { input: Infinity,   errorType: RangeError,  label: "Infinity"          },
  { input: -Infinity,  errorType: RangeError,  label: "-Infinity"         },
  { input: NaN,        errorType: TypeError,   label: "NaN"               },
  { input: "25",       errorType: TypeError,   label: "string number"     },
  { input: "adult",    errorType: TypeError,   label: "string text"       },
  { input: null,       errorType: TypeError,   label: "null"              },
  { input: undefined,  errorType: TypeError,   label: "undefined"         },
  { input: true,       errorType: TypeError,   label: "boolean"           },
  { input: [],         errorType: TypeError,   label: "array"             },
  { input: {},         errorType: TypeError,   label: "object"            },
];

console.log("\n=== Invalid Input Tests ===");
invalidTests.forEach(({ input, errorType, label }) => {
  try {
    classifyAge(input);
    console.log(`❌ FAIL | classifyAge(${label}) — expected ${errorType.name} but no error was thrown`);
  } catch (error) {
    const status = error instanceof errorType ? "✅ PASS" : "❌ FAIL";
    console.log(`${status} | classifyAge(${label}) → ${error.constructor.name}: ${error.message}`);
  }
});
```

