## `validateUser` Function

```javascript
/**
 * Validates a user object for required fields and constraints.
 *
 * @param {Object} user - The user object to validate.
 * @param {string} user.name - The user's name.
 * @param {string} user.email - The user's email address.
 * @param {number} user.age - The user's age.
 * @returns {string|null} An error message string if validation fails, or null if valid.
 */
function validateUser(user) {
  if (!user || typeof user !== "object") {
    return "Invalid input: user must be an object.";
  }

  if (!user.name || typeof user.name !== "string" || user.name.trim() === "") {
    return "Validation error: Name is missing or empty.";
  }

  if (
    !user.email ||
    typeof user.email !== "string" ||
    user.email.trim() === ""
  ) {
    return "Validation error: Email is missing or empty.";
  }

  if (user.age === undefined || user.age === null) {
    return "Validation error: Age is missing.";
  }

  if (typeof user.age !== "number" || isNaN(user.age)) {
    return "Validation error: Age must be a valid number.";
  }

  if (user.age < 18) {
    return `Validation error: Age must be 18 or older (provided: ${user.age}).`;
  }

  return null;
}
```

