```javascript
function classifyAge(age) {
  if (typeof age !== "number" || Number.isNaN(age) || age < 0) {
    throw new TypeError("age must be a non-negative number");
  }

  if (age < 13) return "child";
  if (age < 20) return "teen";
  if (age < 65) return "adult";
  return "senior";
}
```

