 * @throws {Error} If the code is not an integer between 100 and 599.
 */
function httpStatusBucket(code) {
  // 1. Validate the input (same as before)
  if (typeof code !== 'number' || !Number.isInteger(code) || code < 100 || code > 599) {
    throw new Error('Invalid input. Status code must be an integer between 100 and 599.');
  }

  // 2. Get the first digit to determine the category
  const firstDigit = Math.floor(code / 100);

  switch (firstDigit) {
    case 1: return "info";
    case 2: return "success";
    case 3: return "redirect";
    case 4: return "client-error";
    case 5: return "server-error";
    // A default case is not strictly necessary due to the initial validation,
    // but it's good practice for robustness.
    default:
      throw new Error('Unexpected error: code passed validation but could not be categorized.');
  }
}
